function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(57001);
var T0=Date.now();
var W=1000;
var w=new Float32Array(W);for(var i=0;i<W;i++)w[i]=R()*2-1;
var t0=Date.now(),s=0;for(var i=0;i<W;i++)s+=w[i]*w[i];var tFP=Date.now()-t0;
var q=new Int8Array(W);for(var i=0;i<W;i++)q[i]=Math.max(-127,Math.min(127,Math.round(w[i]*100)));
t0=Date.now();var s2=0;for(var i=0;i<W;i++){var v=q[i]/100;s2+=v*v;}var tINT=Date.now()-t0;
var rel=Math.abs(s-s2)/(Math.abs(s)||1);
console.log(JSON.stringify({id:"JAH-APX57-000001",ok:true,metrics:{weights:W,fp32_bytes:W*4,int8_bytes:W,size_ratio:4,fp32_dot_ms:tFP,int8_dot_ms:tINT,quant_rel_err:+rel.toExponential(2)},ms:Date.now()-T0}));

